# Find the thirteen adjacent digits
#  in the 1000-digit number that have the greatest product. What is the value of this product?

from math import prod

text = ''

def mult(var):
#    var = int(var)
   return prod(map(int,str(var)))




res = 0 
for n in range(len(text)):
    var = text[n:n + 13]
    if '0' in var:
        continue
    if mult(var) > res:
        res = mult(var)


print(res)
